    },
    {
      "compound": "Stizolobic acid",
      "amount": "unknown",
      "effect": "Amino acid derivative that may act on glutamate receptors and contribute to the neurotoxic syndrome."
    },
    {
      "compound": "Stizolobinic acid",
      "amount": "unknown",
      "effect": "Related excitatory amino acid derivative thought to add to the central nervous effects of the poisoning."
    },
    {
      "compound": "Muscarine",
      "amount": "approx. 0.0001–0.001 mg/g fresh weight (trace)",
      "effect": "Muscarinic acetylcholine agonist, but present only in traces so cholinergic symptoms are usually negligible."
    },
    {
      "compound": "Trehalose and mannitol (soluble carbohydrates)",
