      "compound": "Chitin and other cell-wall polysaccharides",
      "amount": "approx. 50–100 mg/g dry weight",
      "effect": "Indigestible fibre that can cause gastrointestinal discomfort if the mushroom is eaten raw."
    },
    {
      "compound": "Water",
      "amount": "approx. 88–92 % of fresh weight",
      "effect": "No pharmacological effect; determines the fresh-to-dry weight ratio of the toxins."
    },
    {
      "compound": "Amatoxins / phallotoxins (e.g. alpha-amanitin)",
      "amount": "unknown (generally not detected in this species)",
      "effect": "If present they would inhibit RNA polymerase II and cause liver failure, but A. pantherina poisoning is isoxazole-type, not amatoxin-type."
    }
  ]
}

{
  "mushroom": "Amanita phalloides (death cap), fruiting bodies",
  "composition": [
    {
      "compound": "alpha-Amanitin (bicyclic octapeptide amatoxin)",
      "amount": "~200-400 mg/kg fresh weight (roughly 1-2 mg/g dry weight; highly variable)",
      "effect": "Potently inhibits RNA polymerase II, halting mRNA synthesis and causing fatal liver and kidney necrosis after ingestion of a single cap."
    },
    {
      "compound": "beta-Amanitin",
      "amount": "~20-150 mg/kg fresh weight",
      "effect": "Inhibits RNA polymerase II like alpha-amanitin and contributes to the delayed hepatorenal poisoning syndrome."
    },
    {
      "compound": "gamma-Amanitin",
      "amount": "unknown (minor component)",
      "effect": "Amatoxin that blocks RNA polymerase II and adds to the overall lethal toxicity."
    },
    {
      "compound": "Amaninamide and amanin (amanitin derivatives)",
      "amount": "unknown (trace)",
      "effect": "Inhibit RNA polymerase II, contributing to hepatotoxicity."
    },
    {
      "compound": "Phalloidin (bicyclic heptapeptide phallotoxin)",
      "amount": "~50-200 mg/kg fresh weight (approximate, variable)",
      "effect": "Binds and stabilizes F-actin, destroying liver cell architecture if injected, but is poorly absorbed from the gut so it adds little to oral toxicity."
    },
    {
      "compound": "Phallacidin",
      "amount": "unknown",
      "effect": "Actin-binding phallotoxin that is cytotoxic parenterally but largely inactive when eaten."
    },
    {
      "compound": "Phalloin, phallisin, phallisacin (other phallotoxins)",
      "amount": "unknown (trace)",
      "effect": "Bind F-actin and are hepatotoxic in injection experiments, with minimal oral activity."
    },
    {
      "compound": "Phallolysin (hemolytic protein)",
      "amount": "unknown",
      "effect": "Lyses red blood cells in vitro but is destroyed by heat and gastric digestion, so it is not a significant factor in cooked-mushroom poisoning."
    },
    {
      "compound": "Antamanide (cyclic decapeptide)",
      "amount": "unknown (trace)",
      "effect": "Experimentally antagonizes phalloidin uptake into hepatocytes; no protective effect in real poisonings."
    },
    {
      "compound": "Trehalose and mannitol (soluble carbohydrates/polyols)",
      "amount": "~2-10% of dry weight (combined, approximate)",
      "effect": "Nutritional sugars typical of fungal tissue, harmless in themselves."
    },
    {
      "compound": "Ergosterol (membrane sterol)",
      "amount": "unknown",
      "effect": "Fungal membrane sterol and provitamin D2, nutritionally insignificant here."
    },
    {
      "compound": "Water",
      "amount": "~88-92% of fresh weight",
      "effect": "No pharmacological effect; toxins remain fully active after cooking or drying."
    }
  ]
}

